<script setup lang="ts">import { computed } from 'vue';import { useCalendarStore } from '../../stores/calendar.store';const c=useCalendarStore();const list=computed(()=>c.sortedEvents.filter(e=>new Date(e.start).toDateString()===c.cursor.toDateString()));</script><template><div class="day-list"><div v-if="!list.length" class="empty">Nessun evento per questo giorno.</div><article v-for="e in list" :key="e.id" class="card glass"><div class="eyebrow">{{e.allDay?'Tutto il giorno':new Date(e.start).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}}</div><h3>{{e.title}}</h3><p v-if="e.location">{{e.location}}</p><p v-if="e.description" class="muted">{{e.description}}</p></article></div></template><style scoped>.day-list{display:grid;gap:.7rem;max-width:900px;margin:auto}.day-list h3{margin:.35rem 0}.day-list p{margin:.25rem 0}</style>
